<?php
namespace Tests\Feature;
use App\Models\{Company,User,Customer,Appointment,PatientFollowup,FinancialQuote,FinancialInstallment,FinancialPayment,FinancialExpense,ExpensePayment};
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\{Str,Carbon};
use Tests\TestCase;
class DashboardTest extends TestCase {
 use RefreshDatabase;
 private Company $company;private User $owner;private User $dentist;private Customer $patient;
 protected function setUp():void{parent::setUp();$this->travelTo(Carbon::parse('2026-10-02 01:00:00','UTC'));$this->company=Company::create(['name'=>'Clínica teste','slug'=>'dash','booking_timezone'=>'America/Sao_Paulo']);$this->owner=$this->user('owner');$this->dentist=$this->user('professional');$this->patient=Customer::create(['company_id'=>$this->company->id,'name'=>'Paciente painel','active'=>true]);$this->actingAs($this->owner);}
 private function user(string $role):User{return User::create(['company_id'=>$this->company->id,'name'=>'Usuário '.$role,'email'=>Str::uuid().'@example.test','password'=>'OnlyTest-2026','role'=>$role,'active'=>true]);}
 private function appointment(string $start,string $status='scheduled',?User $dentist=null):Appointment{return Appointment::create(['company_id'=>$this->company->id,'professional_id'=>($dentist??$this->dentist)->id,'created_by'=>$this->owner->id,'client_name'=>'Paciente '.$start.' '.$status,'service'=>'Consulta','starts_at'=>$start,'ends_at'=>Carbon::parse($start)->addMinutes(30),'status'=>$status]);}
 public function test_local_day_midnight_and_statuses_have_correct_boundaries():void{$this->appointment('2026-10-01 00:00');$this->appointment('2026-10-01 23:30','confirmed');$this->appointment('2026-10-01 09:00','completed');$this->appointment('2026-10-01 10:00','no_show');$this->appointment('2026-10-01 11:00','cancelled');$tomorrow=$this->appointment('2026-10-02 00:00');$this->appointment('2026-09-30 23:30');$this->appointment('2026-10-02 01:00','cancelled');$this->appointment('2026-10-02 02:00','completed');$this->get(route('dashboard'))->assertOk()->assertHeader('Cache-Control','no-store, private')->assertViewHas('today','2026-10-01')->assertViewHas('appointmentsToday',4)->assertViewHas('unconfirmedToday',1)->assertViewHas('completedToday',1)->assertViewHas('cancelledToday',1)->assertViewHas('todayAppointments',fn($rows)=>$rows->count()===4)->assertViewHas('nextAppointments',fn($rows)=>$rows->count()===1&&$rows->first()->id===$tomorrow->id);}
 public function test_professional_sees_only_own_schedule_and_no_admin_data():void{$this->appointment('2026-10-01 10:00');$other=$this->user('professional');$hidden=$this->appointment('2026-10-01 11:00','scheduled',$other);$this->appointment('2026-10-02 11:00','confirmed',$other);$this->flushSession();$this->actingAs($this->dentist)->get(route('dashboard'))->assertOk()->assertViewHas('appointmentsToday',1)->assertViewHas('administrative',false)->assertViewHas('followupCounts',null)->assertViewHas('receivables',null)->assertViewHas('payables',null)->assertDontSee('A receber até hoje')->assertDontSee('Lista de espera')->assertDontSee($hidden->client_name);}
 private function followup(string $kind,string $date,string $status='pending'):void{PatientFollowup::create(['company_id'=>$this->company->id,'customer_id'=>$this->patient->id,'created_by'=>$this->owner->id,'kind'=>$kind,'from_date'=>$date,'period'=>'any','status'=>$status,'request_key'=>hash('sha256',(string)Str::uuid())]);}
 public function test_open_followups_due_today_and_overdue_only():void{$this->followup('recall','2026-09-01');$this->followup('recall','2026-10-01','contacted');$this->followup('waitlist','2026-10-01');$this->followup('waitlist','2026-10-02');$this->followup('recall','2026-09-01','scheduled');$this->followup('recall','2026-09-01','closed');$this->get(route('dashboard'))->assertOk()->assertViewHas('followupCounts',fn($c)=>(int)$c['recall']===2&&(int)$c['waitlist']===1)->assertViewHas('dueFollowups',fn($rows)=>$rows->count()===3);$this->flushSession();$this->actingAs($this->user('reception'))->get(route('dashboard'))->assertOk()->assertSee('A receber até hoje')->assertSee('Paciente painel');}
 public function test_financial_balances_include_overdue_and_exclude_future_cancelled_and_reversed_payments():void{
  $q=FinancialQuote::create(['company_id'=>$this->company->id,'customer_id'=>$this->patient->id,'created_by'=>$this->owner->id,'customer_name'=>$this->patient->name,'description'=>'Tratamento','gross_cents'=>30000,'total_cents'=>30000,'status'=>'approved','request_key'=>hash('sha256','q')]);
  foreach(['2026-09-01','2026-10-01','2026-10-02'] as $idx=>$date){$i=FinancialInstallment::create(['company_id'=>$this->company->id,'quote_id'=>$q->id,'sequence'=>$idx+1,'due_on'=>$date,'amount_cents'=>10000]);if($idx===0){foreach([null,now()] as $n=>$reversed)FinancialPayment::create(['company_id'=>$this->company->id,'installment_id'=>$i->id,'created_by'=>$this->owner->id,'amount_cents'=>1000,'paid_on'=>'2026-09-01','method'=>'pix','request_key'=>hash('sha256','p'.$n),'reversed_at'=>$reversed]);}}
  $cancelled=$q->replicate();$cancelled->status='cancelled';$cancelled->request_key=hash('sha256','q2');$cancelled->save();FinancialInstallment::create(['company_id'=>$this->company->id,'quote_id'=>$cancelled->id,'sequence'=>1,'due_on'=>'2026-09-01','amount_cents'=>999999]);
  foreach([['2026-09-01','active'],['2026-10-01','active'],['2026-10-02','active'],['2026-09-01','cancelled']] as $idx=>[$date,$state]){$e=FinancialExpense::create(['company_id'=>$this->company->id,'created_by'=>$this->owner->id,'description'=>'Despesa','category'=>'supplies','due_on'=>$date,'amount_cents'=>5000,'status'=>$state,'request_key'=>hash('sha256','e'.$idx)]);if($idx===0){foreach([null,now()] as $n=>$reversed)ExpensePayment::create(['company_id'=>$this->company->id,'expense_id'=>$e->id,'created_by'=>$this->owner->id,'amount_cents'=>500,'paid_on'=>'2026-09-01','method'=>'pix','request_key'=>hash('sha256','ep'.$n),'reversed_at'=>$reversed]);}}
  $this->get(route('dashboard'))->assertOk()->assertViewHas('receivables',fn($s)=>(int)$s->pending===19000&&(int)$s->overdue===9000)->assertViewHas('payables',fn($s)=>(int)$s->pending===9500&&(int)$s->overdue===4500)->assertSee('R$ 190,00')->assertSee('R$ 95,00');
  $this->appointment('2026-10-01 10:00');$this->followup('recall','2026-10-01');$company=Company::create(['name'=>'Outra clínica','slug'=>'dash-other']);$other=$this->user('owner');$other->update(['company_id'=>$company->id]);$this->flushSession();$this->actingAs($other)->get(route('dashboard'))->assertOk()->assertViewHas('appointmentsToday',0)->assertViewHas('dueFollowups',fn($r)=>$r->isEmpty())->assertViewHas('receivables',fn($s)=>(int)$s->pending===0)->assertViewHas('payables',fn($s)=>(int)$s->pending===0)->assertDontSee('Paciente painel');
 }
}
